css:
/* Nutrition Facts: actual 100 x 70 mm label, not A4. */
@page { size: 100mm 70mm; margin: 0; }
html, body {
  width: 100mm !important;
  min-width: 0 !important;
  max-width: 100mm !important;
  height: 70mm !important;
  min-height: 0 !important;
  max-height: 70mm !important;
  margin: 0 !important;
  padding: 0 !important;
}
.print-format, .print-format-doc {
  width: 100mm !important;
  max-width: 100mm !important;
  height: 70mm !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  box-sizing: border-box;
  background: #fff !important;
}
@media print {
  .print-format .taj-label { break-inside: avoid; page-break-inside: avoid; }
  .taj-label { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
}
.print-format th {background-color:#fff !important;}
.taj-label,.taj-label * {box-sizing:border-box;}
.taj-label {position:relative;width:100mm;height:70mm;overflow:hidden;color:#101010;background:#fff;direction:rtl;text-align:right;font-family:"Dubai Medium","Dubai","Noto Sans Arabic",Tahoma,Arial,sans-serif;font-weight:400;}
.taj-label p {margin:0;}
.taj-label strong,.taj-label b {font-weight:700;}
.label-b {padding:1.6mm;font-size:8.1px;line-height:1.28;border:1.1px solid #111;}
.label-b .b-head {border-bottom:2.5px solid #111;height:28px;display:flex;align-items:center;justify-content:space-between;gap:6px;}
.label-b .b-title {font-weight:800;font-size:16px;max-width:70%;overflow:hidden;line-height:1.08;}
.label-b .b-subb {font-size:10px;white-space:nowrap;}
.label-b .b-subb i {display:inline-block;border-left:1px solid #888;height:8px;vertical-align:middle;margin:0 3px;}
.label-b .b-body {display:grid;grid-template-columns:minmax(0,45fr) minmax(0,55fr);gap:5px;margin-top:3px;}
.label-b .b-nut {border:1px solid #111;min-width:0;}
.label-b .b-label {background:#000 !important;color:#fff !important;font-size:10.5px;text-align:center;font-weight:800;padding:3px 1px;}
.label-b .b-cal {display:flex;justify-content:space-between;align-items:center;font-size:8.3px;padding:2px 3px 0;border-bottom:2px solid #111;}
.label-b .b-cal b {font-size:14px;white-space:nowrap;}
.label-b .b-cal small {font-size:7px;}
.label-b .nut-table {border-collapse:collapse;width:100%;border-spacing:0;table-layout:fixed;direction:rtl;font-size:9px;line-height:1.25;}
.label-b .nut-table tr {page-break-inside:avoid;break-inside:avoid;}
.label-b .nut-table th {width:51%;font-weight:400;text-align:right;}
.label-b .nut-table .qty {width:33%;text-align:center;}
.label-b .nut-table .pct {width:16%;text-align:center;font-weight:700;}
.label-b .nut-table th,.label-b .nut-table td {height:12.5px;border-bottom:1px solid #aaa;padding:0 1px;vertical-align:middle;white-space:nowrap;}
.label-b .b-daily {padding:2px 3px;font-size:7.5px;line-height:1.46;}
.label-b .b-description {padding-right:1px;font-size:10px;line-height:1.36;min-width:0;}
.label-b .b-description .info-line {margin:0 0 6px;overflow-wrap:break-word;}
.label-b .b-description .info-line:last-child {margin-bottom:0;}
.label-b .b-description .b-alert {padding:3px;border-right:3px solid #111;font-weight:600;background:#fff !important;}
.label-b .taj-mini-icon {display:inline-block;height:9px;width:9px;border:1px solid #111;border-radius:2px;color:#111;font:700 8px/7px Arial,sans-serif;text-align:center;vertical-align:middle;margin-left:3px;margin-top:-1px;}
.label-b .taj-icon-allergen,.label-b .taj-icon-warning {border-radius:50%;}
.label-b .taj-icon-storage {font-size:11px;line-height:6px;}
.label-b .taj-icon-location {border:0;font-size:11px;line-height:8px;}
.label-b .taj-footer.taj-footer-single {position:absolute;left:1.6mm;right:1.6mm;bottom:1.2mm;border-top:1px solid #111;padding-top:6px;background:#fff;color:#111;text-align:center;font-size:7.5px;line-height:1;font-weight:400;white-space:nowrap;}
.label-b .taj-footer strong {font-weight:800;}
.label-b .taj-footer-single .taj-footer-line {display:block;white-space:nowrap;}


.label-b .b-label small {font-size:7.1px;font-weight:600;}

/* FPL caloric and net weight layout v1 */
.label-b .b-cal { gap: 2px; white-space: nowrap; }
.label-b .b-cal-main { display: inline-flex; align-items: baseline; white-space: nowrap; gap: 2px; min-width: 0; }
.label-b .b-cal-main > span { font-size: 8px; }
.label-b .b-cal-main > b { font-size: 11px; font-weight: 800; }
.label-b .b-cal-main > b small { font-size: 6.5px; }
.label-b .b-cal-net { font-size: 6.2px; font-weight: 500; white-space: nowrap; flex-shrink: 0; }
.label-b .b-cal-net b { font-size: 7px; font-weight: 700; }
/* TAJ_NUTRITION_CHROME_MARGIN_V5 */
.print-format { margin-top:0mm; margin-right:0mm; margin-bottom:0mm; margin-left:0mm; }
@page { size:100mm 70mm; margin:0mm; }

html:
{# TAJ_NUTRITION_AUTO_V2: approved 100-g source, optional authorized Item print context #}
{% set taj_requested_item = frappe.form_dict.get('taj_print_item') or doc.get('item_code') %}
{% set taj_label = get_public_print_context(doc, taj_requested_item) %}
{% if not taj_label.ok %}{{ frappe.throw(_(taj_label.error)) }}{% endif %}
{# TAJ_NUTRITION_AR_LITERAL_V1: Arabic print labels independent of frappe translations. #}
{% if not taj_label.item_name_ar %}{{ frappe.throw("لا يمكن طباعة الملصق العربي: يرجى تعبئة اسم الصنف بالعربية (Item Name (Arabic)) في بطاقة الصنف.") }}{% endif %}
{% set ar_nutrients = {
  'total_fat_g': 'مجموع الدهون',
  'saturated_fat_g': 'دهون مشبعة',
  'trans_fat_g': 'دهون متحولة',
  'sodium_mg': 'الصوديوم',
  'cholesterol_mg': 'الكوليسترول',
  'carbohydrates_g': 'إجمالي الكربوهيدرات',
  'dietary_fiber_g': 'الألياف الغذائية',
  'total_sugars_g': 'إجمالي السكريات',
  'added_sugars_g': 'السكر المضاف',
  'protein_g': 'البروتين'
} %}
{% set ar_allergens = {
  'Gluten': 'الجلوتين',
  'Milk': 'الحليب',
  'Eggs': 'البيض',
  'Fish': 'الأسماك',
  'Crustaceans': 'القشريات',
  'Molluscs': 'الرخويات',
  'Peanuts': 'الفول السوداني',
  'Tree Nuts': 'المكسرات',
  'Soybeans': 'فول الصويا',
  'Sesame': 'السمسم',
  'Mustard': 'الخردل',
  'Celery': 'الكرفس',
  'Lupin': 'الترمس',
  'Sulphites': 'الكبريتيت'
} %}

{# Nutritional reference: source document, exactly per 100 g; no Item weight or variant enumeration. #}
{% macro digits(raw) -%}
{{- (raw | string) | replace('0','٠') | replace('1','١') | replace('2','٢') | replace('3','٣') | replace('4','٤') | replace('5','٥') | replace('6','٦') | replace('7','٧') | replace('8','٨') | replace('9','٩') -}}
{%- endmacro %}
{% macro num(value) -%}
{%- set n = (value or 0) | float -%}
{{- digits((n | int) if n == (n | int) else (n | round(2))) -}}
{%- endmacro %}
{% macro is_less(nutrient) -%}
{%- set x = namespace(found=false) -%}
{%- for rule in doc.get('amount_rules') or [] -%}
  {%- if rule.get('nutrient') == nutrient and rule.get('less_than_one') -%}
    {%- set x.found = true -%}
  {%- endif -%}
{%- endfor -%}
{{- '1' if x.found else '0' -}}
{%- endmacro %}
{% macro qty(nutrient, value, unit) -%}
{%- if is_less(nutrient) == '1' -%}
{{- 'أقل من' }} {{ num(1) }} {{ ('ملجم' if unit == 'mg' else 'جم') -}}
{%- else -%}
{{- num(value) }} {{ ('ملجم' if unit == 'mg' else 'جم') -}}
{%- endif -%}
{%- endmacro %}
{% macro dv(nutrient, value, reference) -%}
{%- if reference and is_less(nutrient) != '1' -%}
{{- digits((((value or 0)|float) * 100 / reference + 0.5) | int) }}٪
{%- endif -%}
{%- endmacro %}
{# 14 Check fields are the single source for declared allergens. #}
{% set selected_allergens = namespace(values=[]) %}
{% for field, caption in [
  ('allergen_gluten','Gluten'),
  ('allergen_milk','Milk'),
  ('allergen_eggs','Eggs'),
  ('allergen_fish','Fish'),
  ('allergen_crustaceans','Crustaceans'),
  ('allergen_molluscs','Molluscs'),
  ('allergen_peanuts','Peanuts'),
  ('allergen_tree_nuts','Tree Nuts'),
  ('allergen_soybeans','Soybeans'),
  ('allergen_sesame','Sesame'),
  ('allergen_mustard','Mustard'),
  ('allergen_celery','Celery'),
  ('allergen_lupin','Lupin'),
  ('allergen_sulphites','Sulphites')
] %}
  {% if doc.get(field) %}{% set selected_allergens.values = selected_allergens.values + [ar_allergens[caption]] %}{% endif %}
{% endfor %}
{% set allergen_text = selected_allergens.values | join('، ') %}
{% set rows = taj_label.rows %}
{% set p = {
 'item_name': taj_label.item_name_ar,
 'calories': taj_label.calories,
 'rows': rows,
 'ingredients_ar': doc.get('ingredients_ar') or '',
 'allergens_ar': allergen_text
} %}
{# Net weight is only unambiguous for one concrete Item with a positive weight. #}
{# Nutrition values below remain those recorded per 100 g, never scaled by this weight. #}
{% set pack = namespace(value=(taj_label.weight_display if taj_label.mode == 'per_pack' else none), unit='جم') %}

<!-- QC reference values per 100 g. No net weight or package scaling. -->
<div class="taj-label label-b" dir="rtl">
  <header class="b-head">
    <div class="b-title">{{ p.item_name | e }}</div>
    <div class="b-subb">
      {% if taj_label.mode == 'per_pack' %}
      {{ "الوزن الصافي:" }} <b>{{ pack.value }} {{ pack.unit }}</b>
      {% else %}<b>{{ "لكل ١٠٠ جم" }}</b>{% endif %}
    </div>
  </header>
  <div class="b-body">
    <section class="b-nut">
      <div class="b-label">{{ "الحقائق الغذائية" }}</div>
      <div class="b-cal">
  <span class="b-cal-main"><span>{{ "السعرات الحرارية" }}</span><b>{{ p.calories }} <small>{{ "كالوري" }}</small></b></span>
  <span class="b-cal-net">{% if taj_label.mode == 'per_pack' %}{{ "القيم الغذائية لكل:" }} {{ pack.value }} {{ pack.unit }}{% else %}{{ "لكل ١٠٠ جم" }}{% endif %}</span>
</div>
      <table class="nut-table b-table" aria-label="{{ "القيم الغذائية" }}"><tbody>
      {% for r in p.rows %}
        <tr><th scope="row">{{ ar_nutrients[r.field] | e }}</th><td class="qty">{{ (r.amount | replace('Less than', 'أقل من') | replace(' mg', ' ملجم') | replace(' g', ' جم')) | e }}</td><td class="pct">{{ r.percent | e }}</td></tr>
      {% endfor %}
      </tbody></table>
      <p class="b-daily">{{ "نسبة القيمة اليومية محسوبة على أساس نظام غذائي ٢٠٠٠ سعرة حرارية. قد تكون القيمة اليومية الخاصة بك أعلى أو أقل حسب السعرات الحرارية التي تحتاجها." }}</p>
    </section>
    <section class="b-description">
      {% set facility_text = "التصنيع في المنشأة يقوم بمعالجة منتجات الجلوتين والمكسرات والخردل والكرفس والصويا والبيض والرخويات والقشريات والحليب." %}
      {% if (p.allergens_ar or '') | trim %}
      <p class="info-line b-alert"><span class="taj-mini-icon taj-icon-allergen" aria-hidden="true">!</span><strong>{{ "مسببات الحساسية:" }}</strong> {{ p.allergens_ar | e }}</p>
      <p class="info-line b-facility">{{ facility_text | e }}</p>
      {% else %}
      <p class="info-line b-alert"><span class="taj-mini-icon taj-icon-allergen" aria-hidden="true">!</span><strong>{{ "مسببات الحساسية:" }}</strong> {{ facility_text | e }}</p>
      {% endif %}
      <p class="info-line b-ingredients"><span class="taj-mini-icon taj-icon-ingredients" aria-hidden="true">≡</span><strong>{{ "المكونات:" }}</strong> {{ p.ingredients_ar | e }}</p>
      <p class="info-line b-warning"><span class="taj-mini-icon taj-icon-warning" aria-hidden="true">!</span><strong>{{ "التحذيرات:" }}</strong> {{ "لا تأكل من هذه العبوة إذا كان الطعام تالفًا أو إذا كانت العبوة تالفة أو منتفخة. بعد فتح العبوة، يُنصح باستهلاك المحتوى بالكامل فورًا." }}</p>
      <p class="info-line b-storage"><span class="taj-mini-icon taj-icon-storage" aria-hidden="true">°</span><strong>{{ "طريقة التخزين:" }}</strong> {{ "يحفظ في مكان جاف بدرجة حرارة الغرفة لا تتجاوز ٣٠°م، بعيدًا عن أشعة الشمس." }}</p>
    </section>
  </div>
  <div class="taj-footer taj-footer-single" role="contentinfo">
    <span class="taj-footer-line"><span class="taj-mini-icon taj-icon-location" aria-hidden="true">⌂</span>{{ "أُنتج بواسطة" }} <strong>{{ "مصنع تاج الطعام للوجبات الجاهزة" }}</strong>، {{ "منطقة مكة المكرمة - المدينة الصناعية الثانية بجدة - شارع رقم ١٦" }}</span>
  </div>
</div>
